BEGIN;
CREATE TABLE IF NOT EXISTS forge_runtime_config_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),config_key text NOT NULL,scope_type text NOT NULL CHECK (scope_type IN ('GLOBAL','PROVIDER','TENANT','PROJECT','WORKFLOW')),scope_id text NOT NULL,tenant_id text,project_id text,workflow_id text,revision bigint NOT NULL CHECK (revision > 0),value_type text NOT NULL CHECK (value_type IN ('string','integer','number','boolean','object','array','json','secret-ref')),value jsonb NOT NULL DEFAULT 'null'::jsonb,schema jsonb NOT NULL DEFAULT '{}'::jsonb,schema_fingerprint char(64) NOT NULL,state text NOT NULL CHECK (state IN ('DRAFT','STAGED','ACTIVE','PAUSED','ROLLED_BACK','RETIRED')),owner text NOT NULL,activation_start timestamptz,activation_end timestamptz,rollout_percent numeric(5,2) NOT NULL DEFAULT 100 CHECK (rollout_percent BETWEEN 0 AND 100),rollout_cohort text NOT NULL DEFAULT 'stable',prerequisites jsonb NOT NULL DEFAULT '[]'::jsonb,dependencies jsonb NOT NULL DEFAULT '[]'::jsonb,evidence_refs jsonb NOT NULL DEFAULT '[]'::jsonb,previous_revision bigint,rollback_revision bigint,fence_epoch bigint NOT NULL DEFAULT 1 CHECK (fence_epoch > 0),secret boolean NOT NULL DEFAULT false,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,activated_at timestamptz,retired_at timestamptz,CHECK (NOT secret OR value_type='secret-ref'),CHECK (scope_type <> 'TENANT' OR tenant_id IS NOT NULL),CHECK (scope_type <> 'PROJECT' OR project_id IS NOT NULL),CHECK (scope_type <> 'WORKFLOW' OR workflow_id IS NOT NULL));
CREATE UNIQUE INDEX IF NOT EXISTS forge_runtime_config_revision_key_idx ON forge_runtime_config_revisions(scope_type,scope_id,config_key,revision);
CREATE INDEX IF NOT EXISTS forge_runtime_config_effective_idx ON forge_runtime_config_revisions(config_key,scope_type,scope_id,state,activation_start,activation_end,revision DESC);
CREATE INDEX IF NOT EXISTS forge_runtime_config_tenant_idx ON forge_runtime_config_revisions(tenant_id,project_id,config_key,revision DESC);
CREATE TABLE IF NOT EXISTS forge_runtime_config_heads (scope_type text NOT NULL,scope_id text NOT NULL,config_key text NOT NULL,current_revision bigint,generation bigint NOT NULL DEFAULT 0 CHECK (generation >= 0),fence_epoch bigint NOT NULL DEFAULT 0 CHECK (fence_epoch >= 0),kill_switch boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope_type,scope_id,config_key));
CREATE TABLE IF NOT EXISTS forge_runtime_config_rollouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_type text NOT NULL,scope_id text NOT NULL,config_key text NOT NULL,target_revision bigint NOT NULL,previous_revision bigint,status text NOT NULL CHECK (status IN ('STAGED','RUNNING','PAUSED','SUCCEEDED','FAILED','ROLLED_BACK','CANCELLED')),rollout_percent numeric(5,2) NOT NULL DEFAULT 0 CHECK (rollout_percent BETWEEN 0 AND 100),cohort text NOT NULL DEFAULT 'stable',deterministic_seed text NOT NULL,health_window_seconds integer NOT NULL DEFAULT 300 CHECK (health_window_seconds BETWEEN 10 AND 86400),max_error_rate numeric(8,5) NOT NULL DEFAULT 0.05 CHECK (max_error_rate BETWEEN 0 AND 1),max_latency_ms integer CHECK (max_latency_ms IS NULL OR max_latency_ms > 0),auto_rollback boolean NOT NULL DEFAULT true,paused_reason text,actor text NOT NULL,evidence_refs jsonb NOT NULL DEFAULT '[]'::jsonb,fence_epoch bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_runtime_config_rollout_status_idx ON forge_runtime_config_rollouts(status,updated_at DESC);
CREATE INDEX IF NOT EXISTS forge_runtime_config_rollout_target_idx ON forge_runtime_config_rollouts(scope_type,scope_id,config_key,target_revision);
CREATE TABLE IF NOT EXISTS forge_runtime_config_rollout_events (id bigserial PRIMARY KEY,rollout_id uuid NOT NULL REFERENCES forge_runtime_config_rollouts(id) ON DELETE RESTRICT,event_type text NOT NULL,actor text NOT NULL,from_status text,to_status text,from_percent numeric(5,2),to_percent numeric(5,2),reason text,evidence_refs jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_runtime_config_rollout_events_idx ON forge_runtime_config_rollout_events(rollout_id,created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS forge_runtime_config_health_samples (id bigserial PRIMARY KEY,rollout_id uuid NOT NULL REFERENCES forge_runtime_config_rollouts(id) ON DELETE RESTRICT,revision bigint NOT NULL,cohort text NOT NULL,sample_key text NOT NULL,success boolean NOT NULL,latency_ms integer,error_code text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,observed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_runtime_config_health_rollout_idx ON forge_runtime_config_health_samples(rollout_id,observed_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS forge_runtime_config_audit_events (id bigserial PRIMARY KEY,tenant_id text,project_id text,actor text NOT NULL,action text NOT NULL,config_key text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,revision bigint,rollout_id uuid,request_id text,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_runtime_config_audit_scope_idx ON forge_runtime_config_audit_events(tenant_id,project_id,created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS forge_runtime_config_consumer_fences (consumer_id text PRIMARY KEY,consumer_type text NOT NULL,tenant_id text,project_id text,observed_generation bigint NOT NULL DEFAULT 0,observed_fence_epoch bigint NOT NULL DEFAULT 0,config_fingerprint char(64),status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','STALE','FENCED','DRAINING')),last_seen_at timestamptz NOT NULL DEFAULT now(),metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS forge_runtime_config_consumer_stale_idx ON forge_runtime_config_consumer_fences(status,last_seen_at);
CREATE TABLE IF NOT EXISTS forge_runtime_config_schema_registry (config_key text PRIMARY KEY,schema jsonb NOT NULL,schema_fingerprint char(64) NOT NULL,owner text NOT NULL,secret boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION forge_runtime_config_revision_immutable() RETURNS trigger AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.config_key,NEW.scope_type,NEW.scope_id,NEW.revision,NEW.value_type,NEW.value,NEW.schema,NEW.schema_fingerprint,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.config_key,OLD.scope_type,OLD.scope_id,OLD.revision,OLD.value_type,OLD.value,OLD.schema,OLD.schema_fingerprint,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'runtime config revision payload is immutable'; END IF; IF TG_OP='DELETE' THEN RAISE EXCEPTION 'runtime config revisions are immutable'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_runtime_config_revision_immutable_guard ON forge_runtime_config_revisions;
CREATE TRIGGER forge_runtime_config_revision_immutable_guard BEFORE UPDATE OR DELETE ON forge_runtime_config_revisions FOR EACH ROW EXECUTE FUNCTION forge_runtime_config_revision_immutable();
COMMIT;
